import{_ as i}from"./chunks/15-ai-agents.Ct28VXVn.js";import{_ as e,o as a,c as t,a3 as n}from"./chunks/framework.BGhsAJMQ.js";const u=JSON.parse('{"title":"配置 LLM 审核","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/llm-review.md","filePath":"zh/guide/llm-review.md","lastUpdated":1793985812000}'),o={name:"zh/guide/llm-review.md"};function p(l,s,h,d,r,c){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="配置-llm-审核" tabindex="-1">配置 LLM 审核 <a class="header-anchor" href="#配置-llm-审核" aria-label="Permalink to &quot;配置 LLM 审核&quot;">​</a></h1><p>如果要通过 <strong>AI Agents</strong> 向编码代理发送提示词，请在<a href="./install-hub">部署 Hub</a> 后配置 LLM 提供商。提示词审核<strong>默认开启且强制执行</strong>：未配置审核器时，每条提示词都会被拒绝。提供商出错、超时或审核响应无效时也拒绝发送（fail-closed）。</p><p>仅浏览文件或预览时不需要这一步。未配置审核器时，AI Agents 状态、读取输出与白名单按键仍可用；按键不经 LLM 审核。审核器会收到提示词与目标窗口的近期输出，请选择适合处理这些数据的提供商。</p><h2 id="运行配置向导" tabindex="-1">运行配置向导 <a class="header-anchor" href="#运行配置向导" aria-label="Permalink to &quot;运行配置向导&quot;">​</a></h2><p>在 Hub 发布包目录中，先通过 <code>./bin/hub --init-config</code> 创建 <code>config/hub.json</code>，再执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-llm</span></span></code></pre></div><p>使用其他已有配置文件时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-llm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/hub.json</span></span></code></pre></div><ol><li>选择提供商预设或 <strong>Custom</strong>，确认基础 URL、可选端点路径和提供商名称。</li><li>选择环境变量 API key（推荐）或内联密钥。</li><li>从提供商返回的列表中选择模型，或手动输入模型标识。</li><li>向导测试聊天、JSON 输出和带 thinking 的工具调用。测试失败时会询问是否仍保存；请先解决提供商错误，再依赖审核。</li><li>选择将此提供商用于 <strong>AI Agents prompt review</strong>。</li></ol><p>向导保留其他 Hub 设置。选择环境变量存储时，若变量不存在，会询问用于测试的密钥；该测试密钥<strong>不会保存</strong>。还需将变量传给运行中的 Hub，保存后重启 Hub 使配置生效。向导不会关闭审核。</p><h2 id="配置-hub-json" tabindex="-1">配置 <code>hub.json</code> <a class="header-anchor" href="#配置-hub-json" aria-label="Permalink to &quot;配置 \`hub.json\`&quot;">​</a></h2><p>向导写入命名提供商与审核引用。也可将以下字段合并到已有 <code>hub.json</code>；<strong>不要替换认证配置</strong>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;llm_providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deepseek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;chat_completions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;base_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.deepseek.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-flash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;api_key_env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DEEPSEEK_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;timeout_secs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt_review&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>提供商名称以 ASCII 字母或数字开头，仅包含 ASCII 字母、数字、<code>_</code> 或 <code>-</code>，最长 64 个字符。<code>prompt_review.provider</code> 必须引用 <code>llm_providers</code> 中的条目；引用中还可覆盖 <code>model</code> 与 <code>timeout_secs</code>。旧式直接在 <code>prompt_review</code> 下内联提供商配置的方式仍受支持。</p><table tabindex="0"><thead><tr><th>提供商字段</th><th>含义</th></tr></thead><tbody><tr><td><code>protocol</code></td><td><code>chat_completions</code>、<code>responses</code> 或 <code>messages</code></td></tr><tr><td><code>base_url</code></td><td>提供商基础 URL；除回环地址外必须使用 HTTPS。URL 不可包含凭据、查询串或片段。</td></tr><tr><td><code>path</code></td><td>可选端点路径覆盖；必须以 <code>/</code> 开头，不含查询串、片段、<code>..</code> 或空白。</td></tr><tr><td><code>model</code></td><td>用于审核的模型标识</td></tr><tr><td><code>api_key_env</code></td><td>存储 API key 的环境变量名</td></tr><tr><td><code>api_key</code></td><td>也可在私有配置中内联密钥；推荐使用 <code>api_key_env</code></td></tr><tr><td><code>timeout_secs</code></td><td>默认 20 秒。提供商客户端限制为 1–300 秒；Hub 提示词审核限制为 1–60 秒。</td></tr></tbody></table><p>三个协议的默认端点路径依次为 <code>/chat/completions</code>、<code>/responses</code> 和 <code>/anthropic/v1/messages</code>。使用官方 Anthropic API 时，设置 <code>base_url: &quot;https://api.anthropic.com&quot;</code>、<code>path: &quot;/v1/messages&quot;</code>、协议 <code>messages</code>，并选择合适的模型与密钥。</p><h2 id="将-api-key-传给-hub-服务" tabindex="-1">将 API key 传给 Hub 服务 <a class="header-anchor" href="#将-api-key-传给-hub-服务" aria-label="Permalink to &quot;将 API key 传给 Hub 服务&quot;">​</a></h2><p>交互式 shell 中导出的变量不会自动传给 systemd。采用 <a href="./install-hub#systemd-示例可选">systemd 部署</a> 时，在 Hub 单元或 drop-in 的 <code>[Service]</code> 下加入 <code>EnvironmentFile=</code>：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EnvironmentFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/etc/filebox-hub/llm.env</span></span></code></pre></div><p>创建该文件并填入真实密钥（替换占位符），限制为服务管理员可访问，不要纳入版本控制：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=replace-with-your-provider-key</span></span></code></pre></div><p>对于系统服务，可使用 root 所有、权限为 <code>0600</code> 的文件。修改单元后重载 systemd 并重启服务（将 <code>filebox-hub.service</code> 替换为实际单元名）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-hub.service</span></span></code></pre></div><p>手动运行或使用容器时，在启动 Hub 前将同名变量传给 Hub 进程。已配置审核提供商但密钥缺失或为空时，启动配置校验会失败。</p><h2 id="验证审核已配置" tabindex="-1">验证审核已配置 <a class="header-anchor" href="#验证审核已配置" aria-label="Permalink to &quot;验证审核已配置&quot;">​</a></h2><p>打开 <strong>AI Agents</strong>，选择一个窗口，检查是否显示 <strong>Reviewed by deepseek-flash</strong>（或配置的模型）。未配置审核时会显示 <strong>Prompts disabled: configure prompt_review in hub.json</strong>；紧凑布局或手机上显示 <strong>Prompt review not configured</strong>。</p><p><img src="`+i+'" alt="已配置提示词审核的 AI Agents"></p><p>模型标签仅说明已配置，不代表提供商可用。向选中的编码代理发送一条合适的无害提示词，验证能否送达。审核失败时不会转发提示词，草稿仍保留；重试前检查服务的 API key 环境变量、端点、模型与提供商可用性。使用方式与审核边界见 <a href="/filebox/zh/features/ai-agents">AI Agents</a>。</p><h2 id="显式关闭审核" tabindex="-1">显式关闭审核 <a class="header-anchor" href="#显式关闭审核" aria-label="Permalink to &quot;显式关闭审核&quot;">​</a></h2><p>只有确定要<strong>不经 LLM 审核转发提示词</strong>时，才在启动 Hub 时设置 <code>FILEBOX_HUB_PROMPT_REVIEW_ENABLED=0</code>（或 <code>false</code>）。使用 systemd 时，在服务的 <code>[Service]</code> 下加入以下内容，重载 systemd 并重启 Hub：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FILEBOX_HUB_PROMPT_REVIEW_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0</span></span></code></pre></div><p>此设置仅在启动时读取。未设置、<code>1</code>、<code>true</code> 或无效值均保持强制审核。关闭后 AI Agents 显示 <strong>Prompt review off</strong>；仅从 JSON 删除 <code>prompt_review</code> 不会关闭审核。</p><p>接下来：<a href="./install-agent">部署 Agent</a></p>',33)])])}const E=e(o,[["render",p]]);export{u as __pageData,E as default};
